mod tests {
    use super::*;

    #[test]
    fn values_differ_and_shapes_hold() {
        assert_ne!(u64(), u64());
        let h = hex(8);
        assert_eq!(h.len(), 16);
        assert!(h.bytes().all(|b| b.is_ascii_hexdigit()));
        let f = unit_f64();
        assert!((0.0..1.0).contains(&f));
    }
}
