    #[must_use]
    pub fn js_ordered(&self) -> Vec<(&str, &Json)> {
        let mut indexed: Vec<(u32, &str, &Json)> = Vec::new();
        let mut rest: Vec<(&str, &Json)> = Vec::new();
        for (k, v) in &self.entries {
            match array_index(k) {
                Some(i) => indexed.push((i, k, v)),
                None => rest.push((k, v)),
