        let mut checked = 0;
        for line in text.lines() {
            let (bits, expected) = line.split_once(' ').unwrap();
            let x = f64::from_bits(u64::from_str_radix(bits, 16).unwrap());
            let mut out = String::new();
            write_number(&mut out, x);
            assert_eq!(out, expected, "bits {bits}");
            checked += 1;
        }
        assert!(checked > 700);
    }

