        for bad in ["[1,]", "{\"a\":1,}", "01", "1.", "+1", ".5", "1e", "-", "NaN", "nul", "\"\\x41\"", "\"\t\"", "{a:1}", "", " ", "[1] x", "\"abc", "tru"] {
            assert!(parse(bad).is_err(), "{bad:?} should fail");
        }
        for good in ["1e+2", "1e-2", "-0.0", "0.10", "true ", "\t\r\n {} ", "[]", "{}", "\"a\"", "\"\\/\"", "\"\\u0000\""] {
            assert!(parse(good).is_ok(), "{good:?} should parse");
        }
        assert_eq!(parse("-0").unwrap(), Json::Num(-0.0));
        assert!(parse("-0").unwrap().as_f64().unwrap().is_sign_negative());
    }

