        assert_eq!(stringify(&v), "{\"9\":8,\"10\":7,\"b\":1,\"a\":2,\"010\":9,\"4294967295\":0}");
        assert_eq!(stringify_canonical(&v), "{\"010\":9,\"10\":7,\"4294967295\":0,\"9\":8,\"a\":2,\"b\":1}");
