        let mut out = String::new();
        write_string(&mut out, s);
        assert_eq!(out, "\"\\u0000\\u0001\\b\\t\\n\\u000b\\f\\r\\u001f\u{7f}\u{80}\u{2028}\u{2029}\u{feff}\u{10000}\\\"\\\\/\"");
    }

    #[test]
