        assert!(Command::new("git").args(["init", "-q"]).current_dir(&dir).status().unwrap().success());
        assert!(
            Command::new("git")
                .args(["config", "user.email", "conformance@example.invalid"])
                .current_dir(&dir)
                .status()
                .unwrap()
                .success()
        );
        assert_eq!(lookup(Some(&dir)).as_deref(), Some("conformance@example.invalid"));
        assert!(
